    public void applyDiscount(String orderId, String percent) {
        BigDecimal rate = parsePercent(percent);
        Order order = orders.get(orderId);
        Money total = order.total();
        BigDecimal discount = BigDecimal.valueOf(total.minorUnits())
                .multiply(rate)
                .movePointLeft(2)
                .setScale(0, RoundingMode.HALF_UP);
        order.changeTotal(new Money(total.minorUnits() - discount.longValueExact(), total.currency()));
    }

    private static BigDecimal parsePercent(String percent) {
        BigDecimal rate;
        try {
            rate = new BigDecimal(percent.trim());
        } catch (NullPointerException | NumberFormatException e) {
            throw new IllegalArgumentException("Discount percent is not a number: " + percent, e);
        }
        if (rate.signum() < 0 || rate.compareTo(BigDecimal.valueOf(100)) > 0) {
            throw new IllegalArgumentException("Discount percent must be between 0 and 100: " + percent);
        }
        return rate;
    }

